// Tests for the BACKLOG.md items. tests/text.test.js is the pre-existing contract and stays untouched.
const test = require('node:test');
const assert = require('node:assert');
const { slugify } = require('../src/text');

test('cyrillic-slug: slugify transliterates Cyrillic to Latin', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик в тумане'), 'yozhik-v-tumane');
  assert.strictEqual(slugify('Щука, объём и ЮГ'), 'shchuka-obyom-i-yug');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
  // Mixed scripts still produce one clean slug.
  assert.strictEqual(slugify('Node.js для всех'), 'node-js-dlya-vsekh');
});

